, address_data AS ( SELECT proc_inst_id_, text_ AS Address FROM camunda.act_hi_varinst WHERE name_ = ''address'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM basedon_data) ) SELECT task.name_ AS \"Stage\", cuser.vcemailid AS \"Claimed By\", hiproinst.start_time_ AS \"Created Date\", CASE WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \"Status\", pdef.name_ AS \"Case Type\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \"Claimed On\", payer_cte.payer AS \"Payer\", payee_cte.payee AS \"Payee\", transaction_amount_cte.amount AS \"Amount\", ticket_data.Case_ID AS \"Case ID\", alert_data.Alert AS \"Alert\", NULL AS \"Closed Date\", NULL AS \"Closed By\", basedon_data.Alert_Type AS \"Alert Type\", address_data.Address AS \"Address\" FROM camunda.act_ru_task task INNER JOIN filtered_hiproinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ticket_data ON ticket_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN alert_data ON alert_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN basedon_data ON basedon_data.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN address_data ON address_data.proc_inst_id_ = hiproinst.proc_inst_id_ WHERE task.assignee_ IS NOT NULL;",
